    {
      "text": "How many days of paid bereavement leave am I entitled to if an immediate family member passes away?"
    }
  ],
  "role": "user"
}

dataset.response_raw_json:
{
  "parts": [
    {
      "text": "Under corporate policy, you are entitled to up to **5 consecutive paid business days** of Bereavement Leave in the event of the loss of an immediate family member (defined as a spouse, domestic partner, child, parent, or sibling). \n\nTo utilize this time off, requests should be submitted in WorkWeek under the **Bereavement** (or Vacation/PTO) category with notification to your direct manager.\n\nFor full details, please refer to the policy documentation:\n[Global Leave & Time-Off Policy v4.2 - Section 4.2: Bereavement Leave](https://hr-policies.corp.internal/docs/Leave_Policy_v4.2.pdf#page=12)"
    }
  ],
  "role": "model"
}

